    /**
     * Method to retrieve the Enterprise via EnterpriseFetchOneSummary
     * @param 	summary EnterpriseFetchOneSummary 
     * @return 	EnterpriseFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Enterprise getEnterprise( EnterpriseFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "EnterpriseFetchOneSummary arg cannot be null" );
    	
    	Enterprise entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Enterprise
        	// --------------------------------------
        	CompletableFuture<Enterprise> futureEntity = queryGateway.query(new FindEnterpriseQuery( new LoadEnterpriseFilter( summary.getEnterpriseId() ) ), ResponseTypes.instanceOf(Enterprise.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Enterprise with id " + summary.getEnterpriseId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


